function offlinePerformanceMap(){const value=load(OFFLINE_PERFORMANCES_KEY,{});return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}
function saveOfflinePerformanceMap(value){localStorage.setItem(OFFLINE_PERFORMANCES_KEY,JSON.stringify(value||{}))}
function offlineEntry(id){return offlinePerformanceMap()[String(id)]||null}
function isPerformanceOffline(id){return Boolean(offlineEntry(id))}
function mergeOfflinePerformances(list){const out=[...(Array.isArray(list)?list:[])],seen=new Set(out.map(x=>String(x.id)));Object.values(offlinePerformanceMap()).forEach(entry=>{const p=entry&&entry.performance;if(p&&!seen.has(String(p.id))){out.push(p);seen.add(String(p.id))}});return out}
async function savePerformanceOffline(id){const p=state.performances.find(x=>String(x.id)===String(id));if(!p)return alert('No se ha encontrado la actuación.');const map=offlinePerformanceMap();map[String(p.id)]={performance:clone(p),songs:(p.songs||[]).map(songId=>state.songs.find(s=>s.id===songId)).filter(Boolean).map(clone),savedAt:new Date().toISOString(),updatedAt:p.updatedAt||''};saveOfflinePerformanceMap(map);if(p.dancePdfUrl&&'caches' in window){try{const response=await fetch(p.dancePdfUrl,{cache:'reload'});if(response.ok){const cache=await caches.open('valdemedel-dance-pdfs-v417');await cache.put(p.dancePdfUrl,response.clone())}}catch(e){console.warn('No se pudo guardar el PDF para uso sin conexión',e)}}toast('Actuación disponible sin conexión');renderPerformances()}
function removePerformanceOffline(id){const map=offlinePerformanceMap();delete map[String(id)];saveOfflinePerformanceMap(map);toast('Copia sin conexión eliminada');renderPerformances()}
function hydrateOfflineSongs(id){const entry=offlineEntry(id);if(!entry||!Array.isArray(entry.songs))return;entry.songs.forEach(song=>{if(!state.songs.some(s=>s.id===song.id))state.songs.push(clone(song))})}
function networkStatusText(){return navigator.onLine?'En línea':'Sin conexión'}
function mergeNewDefaultSongs(){const key='vm2_catalog_v25';if(localStorage.getItem(key)==='1')return;const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();const current=new Set(state.songs.map(s=>norm(s.title)));let changed=false;for(const s of DEFAULT_SONGS){if(!current.has(norm(s.title))){state.songs.push(clone(s));current.add(norm(s.title));changed=true;}}if(changed){state.songs.sort((a,b)=>a.title.localeCompare(b.title,'es'));localStorage.setItem(STORAGE.songs,JSON.stringify(state.songs));}localStorage.setItem(key,'1');}
mergeNewDefaultSongs();
