function performanceFromRow(row){return {id:String(row.id),name:row.name||'Actuación Valdemedel',date:row.event_date||'',place:row.place||'',songs:Array.isArray(row.songs)?row.songs:[],annotations:row.annotations&&typeof row.annotations==='object'?row.annotations:{},dances:Array.isArray(row.dances)?row.dances:[],dancePdfUrl:row.dance_pdf_url||'',dancePdfName:row.dance_pdf_name||'',dancePdfPath:row.dance_pdf_path||'',participants:Array.isArray(row.participants)?row.participants:[],guestToken:row.guest_token||'',createdAt:row.created_at||'',updatedAt:row.updated_at||''}}
function performanceToRow(p){return {id:String(p.id),name:p.name||'Actuación Valdemedel',event_date:p.date||null,place:p.place||'',songs:Array.isArray(p.songs)?p.songs:[],annotations:p.annotations&&typeof p.annotations==='object'?p.annotations:{},dances:Array.isArray(p.dances)?p.dances:[],dance_pdf_url:p.dancePdfUrl||'',dance_pdf_name:p.dancePdfName||'',dance_pdf_path:p.dancePdfPath||'',participants:Array.isArray(p.participants)?p.participants:[],guest_token:p.guestToken||null,created_at:p.createdAt||new Date().toISOString(),updated_at:p.updatedAt||new Date().toISOString()}}
async function refreshCloudPerformances({silent=false}={}){if(!CLOUD_ENABLED||!cloudClient)return;if(!silent){state.cloudLoading=true;state.cloudError='';if(state.view==='performances')renderPerformances()}try{const {data,error}=await cloudClient.from('performances').select('*').order('event_date',{ascending:false,nullsFirst:false}).order('created_at',{ascending:false});if(error)throw error;state.performances=mergeOfflinePerformances((data||[]).map(performanceFromRow));state.cloudLoading=false;state.cloudError='';state.cloudLastSync=new Date().toISOString();const offlineMap=offlinePerformanceMap();let offlineChanged=false;state.performances.forEach(p=>{if(offlineMap[String(p.id)]){offlineMap[String(p.id)]={performance:clone(p),songs:(p.songs||[]).map(songId=>state.songs.find(s=>s.id===songId)).filter(Boolean).map(clone),savedAt:offlineMap[String(p.id)].savedAt||new Date().toISOString(),updatedAt:p.updatedAt||''};offlineChanged=true}});if(offlineChanged)saveOfflinePerformanceMap(offlineMap);persist();if(state.view==='performances'||state.view==='library')render()}catch(err){console.error('Error al sincronizar actuaciones',err);state.cloudLoading=false;state.cloudError=err?.message||'No se ha podido conectar con la base de datos.';if(state.view==='performances')renderPerformances()}}
function subscribeCloudPerformances(){if(!CLOUD_ENABLED||!cloudClient||cloudChannel)return;cloudChannel=cloudClient.channel('valdemedel-performances').on('postgres_changes',{event:'*',schema:'public',table:'performances'},()=>refreshCloudPerformances({silent:true})).subscribe()}
function offerLegacyPublication(){if(!state.isAdmin||!CLOUD_ENABLED||legacyOfferShown)return;const legacy=localPerformanceBackup();if(!legacy.length)return;legacyOfferShown=true;setTimeout(()=>{if(confirm(`Hay ${legacy.length} actuación${legacy.length===1?'':'es'} guardada${legacy.length===1?'':'s'} en este dispositivo de versiones anteriores. ¿Publicarla${legacy.length===1?'':'s'} ahora para que la vea todo el grupo?`))publishLocalPerformances({skipConfirm:true})},250)}
let cloudInitPromise=null;
async function waitForSupabaseConnector(timeoutMs=12000){const started=Date.now();while(Date.now()-started<timeoutMs){if(window.supabase&&typeof window.supabase.createClient==='function')return true;await new Promise(r=>setTimeout(r,150))}return false}
async function initCloud(){
 if(!CLOUD_ENABLED){state.cloudLoading=false;return false}
 if(cloudClient)return true;
 if(cloudInitPromise)return cloudInitPromise;
 cloudInitPromise=(async()=>{backupLocalPerformances();state.cloudLoading=true;state.cloudError='';
  try{
   const ready=await waitForSupabaseConnector();
   if(!ready)throw new Error('No se ha cargado el conector de Supabase. Recarga la aplicación.');
   cloudClient=window.supabase.createClient(CLOUD_CONFIG.url,CLOUD_CONFIG.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
   const {data,error}=await cloudClient.auth.getSession();if(error)console.warn('Sesión Supabase',error);
   state.isAdmin=isCloudAdminSession(data?.session);state.cloudLoading=false;renderChrome();
   await refreshCloudPerformances({silent:true});subscribeCloudPerformances();offerLegacyPublication();
   cloudClient.auth.onAuthStateChange((_event,session)=>{state.isAdmin=isCloudAdminSession(session);renderChrome();if(state.view==='settings'&&!state.isAdmin)state.view='library';render();offerLegacyPublication()});
   return true;
  }catch(err){console.error('Error al iniciar la nube',err);cloudClient=null;state.cloudLoading=false;state.cloudError=err?.message||'No se ha podido iniciar la sincronización.';render();return false}
  finally{cloudInitPromise=null}
 })();
 return cloudInitPromise;
}
async function upsertCloudPerformance(performance){if(!cloudClient)throw new Error('La base de datos compartida no está conectada.');const {data,error}=await cloudClient.from('performances').upsert(performanceToRow(performance),{onConflict:'id'}).select('*').single();if(error)throw error;if(!data||String(data.id)!==String(performance.id))throw new Error('Supabase no ha confirmado el guardado de la actuación.');return performanceFromRow(data)}
async function removeCloudPerformance(id){if(!cloudClient)throw new Error('La base de datos compartida no está conectada.');const {error}=await cloudClient.from('performances').delete().eq('id',String(id));if(error)throw error}
async function verifyCloudConnection(){if(!cloudClient)return alert('La base de datos compartida no está conectada.');try{const {data:{session}}=await cloudClient.auth.getSession();const {data,error}=await cloudClient.from('performances').select('id').limit(1);if(error)throw error;alert(`Conexión correcta. ${state.isAdmin&&session?'Administrador conectado y preparado para publicar.':'Lectura pública activa.'}
Actuaciones visibles ahora: ${state.performances.length}.`);return data}catch(err){console.error(err);alert('La conexión con Supabase ha fallado: '+(err?.message||'error desconocido')+'\n\nComprueba la conexión y que el SQL de la versión actual se ejecutó correctamente.');return null}}
async function publishLocalPerformances({skipConfirm=false}={}){if(!requireAdmin()||!CLOUD_ENABLED)return;const legacy=localPerformanceBackup();if(!legacy.length)return alert('No hay actuaciones locales pendientes de publicar.');if(!skipConfirm&&!confirm(`Se publicarán ${legacy.length} actuaciones para que las vea todo el grupo. ¿Continuar?`))return;try{const rows=legacy.map(p=>performanceToRow({...p,updatedAt:p.updatedAt||new Date().toISOString()}));const {data,error}=await cloudClient.from('performances').upsert(rows,{onConflict:'id'}).select('id');if(error)throw error;const confirmed=new Set((data||[]).map(x=>String(x.id)));const missing=rows.filter(x=>!confirmed.has(String(x.id)));if(missing.length)throw new Error(`Supabase no confirmó ${missing.length} actuación${missing.length===1?'':'es'}.`);localStorage.setItem(LOCAL_PERFORMANCE_BACKUP_KEY,'[]');await refreshCloudPerformances({silent:true});toast('Actuaciones publicadas para todo el grupo');renderPerformances()}catch(err){console.error(err);alert('No se pudieron publicar las actuaciones: '+(err?.message||'error desconocido'))}}

function requireAdmin(){if(state.isAdmin)return true;alert('Esta función está reservada al usuario administrador.');return false}
async function adminLogin(){
 if(!CLOUD_ENABLED){if(state.isAdmin){if(confirm('¿Cerrar la sesión de administrador?')){state.isAdmin=false;sessionStorage.removeItem('vm_admin');renderChrome();nav('library')}return}const pin=prompt('Introduce el PIN de administrador:');if(pin===null)return;if(pin===ADMIN_PIN){state.isAdmin=true;sessionStorage.setItem('vm_admin','1');renderChrome();toast('Modo administrador activado');render()}else alert('PIN incorrecto.');return}
 if(!cloudClient){const ready=await initCloud();if(!ready||!cloudClient)return alert('No se ha podido conectar con Supabase. Pulsa «Actualizar», espera unos segundos y vuelve a intentarlo.');}
 if(state.isAdmin){if(confirm('¿Cerrar la sesión de administrador?')){await cloudClient.auth.signOut();state.isAdmin=false;renderChrome();nav('library')}return}
 const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card admin-login-card"><div class="modal-head"><div><span class="info-kicker">Acceso seguro</span><h2>Administrador</h2></div><button class="close" id="closeAdminLogin">×</button></div><p class="admin-login-help">Identifícate para crear, modificar y publicar actuaciones para todo el grupo.</p><div class="form-grid"><div class="field full"><label>Correo del administrador</label><input id="adminEmail" type="email" autocomplete="username" value="${esc(CLOUD_CONFIG.adminEmail||'')}"></div><div class="field full"><label>Contraseña</label><input id="adminPassword" type="password" autocomplete="current-password"></div></div><div id="adminLoginError" class="login-error" hidden></div><div class="toolbar"><button class="btn" id="submitAdminLogin">Entrar</button><button class="btn secondary" id="cancelAdminLogin">Cancelar</button></div></div>`;document.body.append(modal);const close=()=>modal.remove();modal.querySelector('#closeAdminLogin').onclick=close;modal.querySelector('#cancelAdminLogin').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};const submit=async()=>{const email=modal.querySelector('#adminEmail').value.trim(),password=modal.querySelector('#adminPassword').value,button=modal.querySelector('#submitAdminLogin'),errorBox=modal.querySelector('#adminLoginError');if(!email||!password){errorBox.textContent='Escribe el correo y la contraseña.';errorBox.hidden=false;return}button.disabled=true;button.textContent='Entrando…';errorBox.hidden=true;const {data,error}=await cloudClient.auth.signInWithPassword({email,password});if(error||!isCloudAdminSession(data?.session)){if(data?.session&&!isCloudAdminSession(data.session))await cloudClient.auth.signOut();errorBox.textContent=error?'No se ha podido iniciar sesión: '+error.message:'Este usuario no está autorizado como administrador.';errorBox.hidden=false;button.disabled=false;button.textContent='Entrar';return}state.isAdmin=true;close();renderChrome();await refreshCloudPerformances({silent:true});toast('Modo administrador conectado');render();offerLegacyPublication()};modal.querySelector('#submitAdminLogin').onclick=submit;modal.querySelector('#adminPassword').onkeydown=e=>{if(e.key==='Enter')submit()};requestAnimationFrame(()=>modal.querySelector('#adminPassword').focus())
}
function renderChrome(){document.body.classList.toggle('admin-mode',state.isAdmin);const backup=document.querySelector('#backupBtn');if(backup)backup.hidden=!state.isAdmin;const admin=document.querySelector('#adminBtn');if(admin){admin.textContent=state.isAdmin?'🔓':'🔒';admin.title=state.isAdmin?'Cerrar sesión de administrador':'Acceso administrador'};const settings=document.querySelector('[data-view="settings"]');if(settings)settings.hidden=!state.isAdmin}
function formatLyricsHtml(text){return String(text||'').replace(/\r\n?/g,'\n').split('\n').map(line=>{const bracket=line.match(/^\s*\[(H|M|T|HOMBRES|MUJERES|TODOS)\]\s*$/i);if(bracket){const raw=bracket[1].toUpperCase();const c=raw==='HOMBRES'?'H':raw==='MUJERES'?'M':raw==='TODOS'?'T':raw;const label=c==='H'?'Hombres':c==='M'?'Mujeres':'Todos';return '<span class="voice-line voice-heading bracket-heading"><span class="voice-badge voice-'+c+'">'+c+'</span><strong>'+label+'</strong></span>'}const m=line.match(/^\s*([HMT])(?:\s*[:.\-])?\s+(.*)$/i);if(m)return '<span class="voice-line"><span class="voice-badge voice-'+m[1].toUpperCase()+'">'+m[1].toUpperCase()+'</span><span>'+esc(m[2])+'</span></span>';const only=line.match(/^\s*(HOMBRES|MUJERES|TODOS)\s*$/i);if(only){const c=only[1].toUpperCase()==='HOMBRES'?'H':only[1].toUpperCase()==='MUJERES'?'M':'T';return '<span class="voice-line voice-heading"><span class="voice-badge voice-'+c+'">'+c+'</span><strong>'+esc(only[1])+'</strong></span>'}return esc(line)||'&nbsp;'}).join('\n')}
function annotationFor(id){return String((state.repAnnotations||{})[id]||'').trim()}
let performanceAutosaveTimer=null;
let performanceAutosaveBusy=false;
function schedulePerformanceAutosave(delay=1200){
 if(!state.isAdmin||!state.editingPerformanceId)return;
 clearTimeout(performanceAutosaveTimer);
 performanceAutosaveTimer=setTimeout(()=>autosaveEditingPerformance(),delay);
}
async function autosaveEditingPerformance(){
 if(performanceAutosaveBusy||!state.isAdmin||!state.editingPerformanceId)return;
 const editing=editingPerformance();if(!editing)return;
 const draft=state.performanceDraft||{};
 const saved={...editing,...draft,songs:[...state.rep],annotations:{...state.repAnnotations},updatedAt:new Date().toISOString()};
 performanceAutosaveBusy=true;
 try{
  if(CLOUD_ENABLED){const confirmed=await upsertCloudPerformance(saved);const i=state.performances.findIndex(p=>String(p.id)===String(confirmed.id));if(i>=0)state.performances[i]=confirmed;else state.performances.unshift(confirmed);state.cloudLastSync=new Date().toISOString()}
  else{const i=state.performances.findIndex(p=>String(p.id)===String(saved.id));if(i>=0)state.performances[i]=saved}
  persist();document.dispatchEvent(new CustomEvent('performance-autosaved'));
 }catch(err){console.error('Autoguardado de actuación fallido',err);document.dispatchEvent(new CustomEvent('performance-autosave-error',{detail:err}))}
 finally{performanceAutosaveBusy=false}
}
function openAnnotation(song,editable=state.isAdmin){const modal=document.createElement('div');modal.className='modal annotation-modal';const value=annotationFor(song.id);modal.innerHTML='<div class="modal-card annotation-card"><div class="modal-head"><div><span class="info-kicker">Indicaciones de la actuación</span><h2>'+esc(song.title)+'</h2></div><button class="close" id="closeAnnotation">×</button></div>'+(editable?'<textarea id="annotationText" placeholder="Ej. Hacer 2 intros, repetir al final, despedida especial...">'+esc(value)+'</textarea><div id="annotationAutosaveStatus" class="autosave-status">Guardado automático activado</div>':'<div class="annotation-read">'+(value?esc(value).replace(/\n/g,'<br>'):'No hay anotaciones para esta canción.')+'</div>')+'<div class="toolbar">'+(editable?'<button class="btn" id="saveAnnotation">Guardar y cerrar</button>':'')+'<button class="btn secondary" id="cancelAnnotation">Cerrar</button></div></div>';document.body.append(modal);const close=()=>{modal.remove();render()};modal.querySelector('#closeAnnotation').onclick=close;modal.querySelector('#cancelAnnotation').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};if(editable){const ta=modal.querySelector('#annotationText'),status=modal.querySelector('#annotationAutosaveStatus');let localTimer=null;const saveLocal=()=>{const v=ta.value.trim();if(v)state.repAnnotations[song.id]=v;else delete state.repAnnotations[song.id];persist();status.textContent=state.editingPerformanceId?'Guardado en borrador · sincronizando…':'Guardado en este dispositivo';status.className='autosave-status saving';schedulePerformanceAutosave(800);clearTimeout(localTimer);localTimer=setTimeout(()=>{if(document.body.contains(status)&&!state.editingPerformanceId){status.textContent='Guardado automáticamente';status.className='autosave-status saved'}},500)};ta.addEventListener('input',saveLocal);const ok=()=>{if(!document.body.contains(status))return;status.textContent='Guardado y publicado';status.className='autosave-status saved'};const fail=()=>{if(!document.body.contains(status))return;status.textContent='Guardado localmente; pendiente de publicar';status.className='autosave-status error'};document.addEventListener('performance-autosaved',ok,{once:true});document.addEventListener('performance-autosave-error',fail,{once:true});modal.querySelector('#saveAnnotation').onclick=async()=>{saveLocal();await autosaveEditingPerformance();close();toast(state.editingPerformanceId?'Anotación guardada y publicada':'Anotación guardada')}}}
function nav(v){if(v==='settings'&&!state.isAdmin)v='library';state.view=v;state.current=null;state.performanceMode=false;render();if(v==='performances'&&CLOUD_ENABLED)refreshCloudPerformances({silent:true})}
function render(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));if(state.performanceMode&&state.current)return renderPerformanceMode();if(state.current)return renderSong();({library:renderLibrary,repertoire:renderRep,performances:renderPerformances,settings:renderSettings}[state.view]||renderLibrary)()}
function normalizeSearch(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').replace(/\s+/g,' ').trim()}
function matchesSearch(song,query){if(!query)return true;const sections=(song.sections||[]).map(x=>`${x.name||''} ${x.chords||''}`).join(' ');const haystack=normalizeSearch([song.title,song.category,song.key,song.generalChords,sections,song.lyrics,song.inlineContent,song.voices,song.notes].join(' '));return query.split(' ').every(term=>haystack.includes(term))}
function updateLibraryResults(){const q=normalizeSearch(state.search);const filtered=state.songs.filter(s=>(state.filter==='Todas'||s.category===state.filter)&&matchesSearch(s,q));const list=$('#songResults'),count=$('#searchCount');if(list)list.innerHTML=filtered.length?filtered.map(songCard).join(''):`<div class="empty">No se han encontrado canciones con esa búsqueda.</div>`;if(count)count.textContent=`${filtered.length} resultado${filtered.length===1?'':'s'}`;bindSongCards()}
function renderLibrary(){const photos=[['actuacion-infantil.jpeg','Grupo infantil en actuación'],['romeria.jpeg','Valdemedel en romería'],['grupo.jpeg','El grupo'],['musicos-escenario.jpeg','Músicos y cantantes'],['festival.jpeg','Festival Folklórico'],['tamborilero.jpeg','Música desde el escenario'],['baile.jpeg','Baile en directo'],['musicos-historicos.jpeg','Memoria del grupo']];app.innerHTML=`<section class="hero apple-hero"><img class="hero-photo" src="baile.jpeg" alt="Grupo Folklórico Valdemedel en actuación"><div class="hero-shade"></div><div class="hero-copy"><span class="eyebrow">Grupo Folklórico Valdemedel</span><h1>Tu repertorio,<br>siempre contigo.</h1><p>${state.songs.length} canciones con letras, acordes e historia para ensayos y actuaciones.</p><div class="hero-stats"><span><b>${state.songs.length}</b> canciones</span><span><b>${state.performances.length}</b> actuaciones</span></div></div><img class="hero-mark" src="logo-blanco.png" alt=""></section><section class="gallery-section"><div class="section-title compact-title"><div><span class="eyebrow dark-eyebrow">Nuestra memoria</span><h2>Valdemedel en imágenes</h2></div><span>Desliza para ver más</span></div><div class="photo-rail">${photos.map((p,i)=>`<button class="photo-card photo-${i+1}" data-photo="${p[0]}" data-caption="${esc(p[1])}"><img src="${p[0]}" alt="${esc(p[1])}" loading="lazy"><span>${esc(p[1])}</span></button>`).join('')}</div></section><div class="section-title"><div><span class="eyebrow dark-eyebrow">Cancionero</span><h2>Todo el repertorio</h2></div>${state.isAdmin?'<button class="btn" id="newSong">＋ Nueva canción</button>':''}</div><div class="search-wrap"><input id="search" class="search" placeholder="Buscar canciones, letras o acordes" value="${esc(state.search)}"><button id="clearSearch" class="clear-search" type="button" aria-label="Borrar búsqueda">×</button></div><div class="search-info" id="searchCount"></div><div class="chips">${categories().map(c=>`<button class="chip ${state.filter===c?'active':''}" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="song-list" id="songResults"></div>`;const search=$('#search');search.oninput=e=>{state.search=e.target.value;updateLibraryResults();$('#clearSearch').classList.toggle('visible',!!state.search)};$('#clearSearch').onclick=()=>{state.search='';search.value='';search.focus();$('#clearSearch').classList.remove('visible');updateLibraryResults()};$('#clearSearch').classList.toggle('visible',!!state.search);$$('[data-cat]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.cat;renderLibrary()});$$('[data-photo]').forEach(b=>b.onclick=()=>openPhoto(b.dataset.photo,b.dataset.caption));if($('#newSong'))$('#newSong').onclick=()=>openEditor();updateLibraryResults()}

function openPhoto(src,caption=''){const modal=document.createElement('div');modal.className='modal photo-lightbox';modal.innerHTML=`<div class="photo-lightbox-card"><button class="photo-lightbox-close" aria-label="Cerrar">×</button><img src="${esc(src)}" alt="${esc(caption)}"><div class="photo-lightbox-caption">${esc(caption)}</div></div>`;document.body.append(modal);const close=()=>modal.remove();modal.querySelector('.photo-lightbox-close').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};document.addEventListener('keydown',function escClose(e){if(e.key==='Escape'){close();document.removeEventListener('keydown',escClose)}})}

function songCard(s){const inRep=state.rep.includes(s.id);const chord=s.chordMode==='general'?(s.generalChords||s.key):s.chordMode==='sections'?'Acordes por partes':s.chordMode==='none'?'Sin acordes':s.chordMode==='inline'?'Acordes sobre letra':'Pendiente';return `<article class="song-card"><div class="badge">♫</div><div class="meta" data-open="${s.id}"><h3>${esc(s.title)}</h3><p>${esc(s.category)} · ${esc(chord)}</p>${statusLabel(s)}</div><button class="btn ${inRep?'secondary':''} small" data-add="${s.id}">${inRep?'✓':'+'}</button></article>`}
function bindSongCards(){$$('[data-open]').forEach(x=>x.onclick=()=>{state.current=x.dataset.open;render()});$$('[data-add]').forEach(x=>x.onclick=e=>{e.stopPropagation();toggleRep(x.dataset.add)})}
function toggleRep(id){state.rep=state.rep.includes(id)?state.rep.filter(x=>x!==id):[...state.rep,id];persist();schedulePerformanceAutosave();render()}
function chordPanel(s){if(s.chordMode==='none')return '<div class="chord-panel"><h3>Acordes</h3><div>Esta canción se muestra sin acordes.</div></div>';if(s.chordMode==='pending')return '<div class="chord-panel"><h3>Acordes</h3><div>Pendientes de completar desde «Editar canción».</div></div>';if(s.chordMode==='inline')return s.key?`<div class="chord-panel"><h3>Tonalidad</h3><div class="chord-line">${esc(s.key)}</div></div>`:'';if(s.chordMode==='general')return `<div class="chord-panel"><h3>${s.key?'Tonalidad: '+esc(s.key):'Acordes generales'}</h3><div class="chord-line">${esc(s.generalChords||s.key)}</div></div>`;return `<div class="chord-panel"><h3>${s.key?'Tonalidad: '+esc(s.key):'Acordes por partes'}</h3>${(s.sections||[]).map(x=>`<div><strong>${esc(x.name)}:</strong> <span class="chord-line">${esc(x.chords)}</span></div>`).join('')}</div>`}
function renderSong(){const s=state.songs.find(x=>x.id===state.current);if(!s){state.current=null;return render()}const idx=state.rep.indexOf(s.id);const text=s.chordMode==='inline'?(s.inlineContent||s.lyrics):s.lyrics;app.innerHTML=`<div class="toolbar no-print"><button class="btn secondary" id="back">← Volver</button><button class="btn" id="add">${state.rep.includes(s.id)?'Quitar del repertorio':'Añadir al repertorio'}</button>${state.isAdmin?'<button class="btn secondary" id="edit">Editar</button>':''}<button class="btn secondary" id="bigger">A+</button><button class="btn secondary" id="smaller">A-</button></div><article class="song-view"><header class="song-head"><h1>${esc(s.title)}</h1><p>${esc(s.category)}${s.duration?' · '+esc(s.duration):''}</p></header>${chordPanel(s)}${s.notes?`<div class="song-notes"><strong>Observaciones:</strong> ${esc(s.notes)}</div>`:''}${s.voices?`<div class="song-notes"><strong>Voces:</strong> ${esc(s.voices)}</div>`:''}<div id="lyrics" class="song-content formatted-lyrics">${formatLyricsHtml(text)}</div></article>${idx>=0?`<div class="toolbar no-print" style="margin-top:12px"><button class="btn secondary" id="prev">← Anterior</button><button class="btn" id="next">Siguiente →</button></div>`:''}`;$('#back').onclick=()=>{state.current=null;render()};$('#add').onclick=()=>toggleRep(s.id);if($('#edit'))$('#edit').onclick=()=>openEditor(s);let size=17;$('#bigger').onclick=()=>{size=Math.min(30,size+1);$('#lyrics').style.fontSize=size+'px'};$('#smaller').onclick=()=>{size=Math.max(12,size-1);$('#lyrics').style.fontSize=size+'px'};if(idx>=0){$('#prev').onclick=()=>{state.current=state.rep[(idx-1+state.rep.length)%state.rep.length];render()};$('#next').onclick=()=>{state.current=state.rep[(idx+1)%state.rep.length];render()}}}
function renderPerformanceMode(){
 const s=state.songs.find(x=>x.id===state.current);if(!s){state.performanceMode=false;state.current=null;return render()}
 const idx=state.rep.indexOf(s.id);const text=String(s.chordMode==='inline'?(s.inlineContent||s.lyrics):s.lyrics||'').replace(/\r\n?/g,'\n').trim();
 const blocks=text.split(/\n[ \t]*\n+/).map(x=>x.trim()).filter(Boolean);
 const infoAvailable=hasSongInfo(s);
 document.body.classList.add('performing');
 app.innerHTML=`<section class="performance-screen"><header class="performance-head"><div><h1>${esc(s.title)}</h1><div class="performance-meta">${esc(s.category||'')}${s.key?' · '+esc(s.key):''}${annotationFor(s.id)?' · <span class="annotation-indicator">Anotación disponible</span>':''}</div></div><div class="performance-actions"><button class="perf-btn info-perf ${infoAvailable?'info-available':'info-pending'}" id="showSongInfo" title="${infoAvailable?'Historia y curiosidades disponibles':'Información todavía pendiente'}">ⓘ <span>${infoAvailable?'Info':'Sin info'}</span></button><button class="perf-btn font-control" id="perfSmaller">A-</button><button class="perf-btn font-control" id="perfBigger">A+</button><button class="perf-btn annotation-perf ${annotationFor(s.id)?'has-annotation':''}" id="showAnnotation">📝 <span>Nota</span></button><button class="perf-btn close-perf" id="exitPerform">Cerrar</button></div></header><div class="performance-chords">${s.chordMode==='general'?esc(s.generalChords||s.key):s.chordMode==='sections'?(s.sections||[]).map(x=>`<b>${esc(x.name)}:</b> ${esc(x.chords)}`).join(' &nbsp; · &nbsp; '):s.chordMode==='pending'?'Acordes pendientes':''}</div><div class="performance-lyrics" id="performanceLyrics"><div class="performance-columns" id="performanceColumns"></div></div><footer class="performance-nav"><button class="perf-nav" id="perfPrev">← Anterior</button><span>${idx+1} / ${state.rep.length}</span><button class="perf-nav" id="perfNext">Siguiente →</button><small class="performance-credit">Creada por Carmona para el Grupo Folklórico Valdemedel</small></footer></section>`;
 const container=$('#performanceColumns');
 function build(cols){container.className='performance-columns cols-'+cols;container.innerHTML='';const cs=[];for(let i=0;i<cols;i++){const c=document.createElement('div');c.className='performance-column';container.append(c);cs.push(c)};if(cols===1){blocks.forEach(b=>{const d=document.createElement('div');d.className='performance-verse';d.innerHTML=formatLyricsHtml(b);cs[0].append(d)});return cs}
 const weights=blocks.map(b=>b.split('\n').length+Math.ceil(b.length/55)*.45);let total=weights.reduce((a,b)=>a+b,0),acc=0,cut=1,best=Infinity;for(let i=1;i<blocks.length;i++){acc+=weights[i-1];const score=Math.abs(total-2*acc);if(score<best){best=score;cut=i}}blocks.forEach((b,i)=>{const d=document.createElement('div');d.className='performance-verse';d.innerHTML=formatLyricsHtml(b);cs[i<cut?0:1].append(d)});return cs}
 let manualDelta=0;
 const performanceArea=$('#performanceLyrics');
 function fits(cols,size){container.style.setProperty('--perf-size',size+'px');const cs=build(cols);void container.offsetHeight;return cs.every(c=>c.scrollHeight<=performanceArea.clientHeight+1&&c.scrollWidth<=c.clientWidth+1)}
 function updateScrollMode(){
  void container.offsetHeight;
  const columns=[...container.querySelectorAll('.performance-column')];
  // Las columnas usan overflow:hidden mientras calculamos el mejor tamaño. Por eso
  // el contenedor puede parecer que cabe aunque una columna tenga versos ocultos.
  // Comprobamos cada columna para activar el desplazamiento siempre que falte texto.
  const columnOverflows=columns.some(c=>
   c.scrollHeight>performanceArea.clientHeight+2||c.scrollWidth>c.clientWidth+2
  );
  const contentOverflows=columnOverflows||container.scrollHeight>performanceArea.clientHeight+2||container.scrollWidth>performanceArea.clientWidth+2;
  const scrollable=manualDelta>0||contentOverflows;
  performanceArea.classList.toggle('is-scrollable',scrollable);
  container.classList.toggle('is-zoomed',scrollable);
  performanceArea.setAttribute('aria-label',scrollable?'Letra completa. Desliza para moverte por toda la canción.':'Letra de la canción');
  if(!scrollable)performanceArea.scrollTo({top:0,left:0});
 }
 function fit(){
  const oldMaxY=Math.max(0,performanceArea.scrollHeight-performanceArea.clientHeight);
  const oldMaxX=Math.max(0,performanceArea.scrollWidth-performanceArea.clientWidth);
  const oldRatioY=oldMaxY?performanceArea.scrollTop/oldMaxY:0;
  const oldRatioX=oldMaxX?performanceArea.scrollLeft/oldMaxX:0;
  const portrait=window.matchMedia('(orientation: portrait)').matches;
  const narrow=window.innerWidth<700;
  const maxSize=narrow?30:(portrait?34:38);
  const minSize=narrow?11:12;
  const preferredCols=portrait?[1,2]:[2,1];
  let candidates=[];
  performanceArea.classList.remove('is-scrollable');
  container.classList.remove('is-zoomed');
  performanceArea.scrollTo({top:0,left:0});
  for(const cols of preferredCols){
    let lo=minSize,hi=narrow?22:(portrait?25:28);
    for(let i=0;i<15;i++){
      const mid=(lo+hi)/2;
      if(fits(cols,mid))lo=mid;else hi=mid;
    }
    candidates.push({cols,size:lo});
  }
  let winner=candidates[0];
  for(const c of candidates){
    const bonus=(portrait&&c.cols===1?1.2:0)+(!portrait&&c.cols===2?.6:0);
    const winnerBonus=(portrait&&winner.cols===1?1.2:0)+(!portrait&&winner.cols===2?.6:0);
    if(c.size+bonus>winner.size+winnerBonus)winner=c;
  }
  const size=Math.max(minSize,Math.min(maxSize,winner.size+manualDelta));
  container.style.setProperty('--perf-size',size+'px');
  build(winner.cols);
  updateScrollMode();
  requestAnimationFrame(()=>{
   if(!performanceArea.classList.contains('is-scrollable'))return;
   const newMaxY=Math.max(0,performanceArea.scrollHeight-performanceArea.clientHeight);
   const newMaxX=Math.max(0,performanceArea.scrollWidth-performanceArea.clientWidth);
   performanceArea.scrollTop=newMaxY*oldRatioY;
   performanceArea.scrollLeft=newMaxX*oldRatioX;
  });
 }
 let drag=null;
 performanceArea.addEventListener('pointerdown',e=>{
  if(!performanceArea.classList.contains('is-scrollable')||e.pointerType!=='mouse'||e.button!==0)return;
  drag={x:e.clientX,y:e.clientY,left:performanceArea.scrollLeft,top:performanceArea.scrollTop};
  performanceArea.classList.add('is-dragging');
  performanceArea.setPointerCapture(e.pointerId);
  e.preventDefault();
 });
 performanceArea.addEventListener('pointermove',e=>{
  if(!drag)return;
  performanceArea.scrollLeft=drag.left-(e.clientX-drag.x);
  performanceArea.scrollTop=drag.top-(e.clientY-drag.y);
 });
 const stopDrag=e=>{if(!drag)return;drag=null;performanceArea.classList.remove('is-dragging');try{performanceArea.releasePointerCapture(e.pointerId)}catch(_){}};
 performanceArea.addEventListener('pointerup',stopDrag);
 performanceArea.addEventListener('pointercancel',stopDrag);
 $('#showSongInfo').onclick=()=>openSongInfo(s);$('#showAnnotation').onclick=()=>openAnnotation(s,state.isAdmin);
 $('#exitPerform').onclick=()=>{document.body.classList.remove('performing');state.performanceMode=false;state.current=null;render()};
 $('#perfPrev').onclick=()=>{state.current=state.rep[(idx-1+state.rep.length)%state.rep.length];render()};$('#perfNext').onclick=()=>{state.current=state.rep[(idx+1)%state.rep.length];render()};
 $('#perfBigger').onclick=()=>{manualDelta=Math.min(14,manualDelta+1);fit()};$('#perfSmaller').onclick=()=>{manualDelta=Math.max(-8,manualDelta-1);fit()};
 requestAnimationFrame(()=>requestAnimationFrame(fit));window.onresize=()=>{if(state.performanceMode)fit()};
}
function openSongInfo(song){
 const history=(song.history||'').trim();
 const curiosities=Array.isArray(song.curiosities)?song.curiosities.filter(Boolean):String(song.curiosities||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);
 const source=(song.infoSource||'').trim();
 const origin=(song.origin||'').trim();
 const hasInfo=history||curiosities.length||source||origin;
 const modal=document.createElement('div');
 modal.className='modal song-info-modal';
 modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-label','Información de '+song.title);
 modal.innerHTML=`<article class="modal-card song-info-card"><div class="modal-head"><div><span class="info-kicker">Historia y curiosidades</span><h2>${esc(song.title)}</h2></div><button class="close" id="closeSongInfo" aria-label="Cerrar">×</button></div>${origin?`<div class="info-origin"><b>Procedencia:</b> ${esc(origin)}</div>`:''}${history?`<section class="info-section"><h3>Historia</h3><p>${esc(history).replace(/\n/g,'<br>')}</p></section>`:''}${curiosities.length?`<section class="info-section"><h3>Curiosidades</h3><ul>${curiosities.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}${source?`<section class="info-source"><b>Fuente:</b> ${esc(source)}</section>`:''}${!hasInfo?`<div class="info-empty">Información pendiente de documentar.</div>`:''}<div class="info-footer"><button class="btn" id="closeSongInfoBottom">Cerrar información</button></div></article>`;
 document.body.append(modal);
 const close=()=>{modal.remove();document.removeEventListener('keydown',onKey)};
 const onKey=e=>{if(e.key==='Escape')close()};
 document.addEventListener('keydown',onKey);
 modal.querySelector('#closeSongInfo').onclick=close;
 modal.querySelector('#closeSongInfoBottom').onclick=close;
 modal.onclick=e=>{if(e.target===modal)close()};
 requestAnimationFrame(()=>modal.querySelector('#closeSongInfo').focus());
}

