 const heading=editing?'Editando actuación':'Repertorio actual';
 const adminForm=state.isAdmin?`<div class="form-card ${editing?'editing-performance-card':''}">${editing?`<div class="editing-performance-notice"><strong>✎ Estás modificando «${esc(editing.name||'Actuación Valdemedel')}»</strong><span>Los cambios sustituirán esta actuación; no se creará una copia nueva.</span></div>`:''}<div class="form-grid"><div class="field full"><label>Nombre de la actuación</label><input id="eventName" value="${esc(draft.name||'')}" placeholder="Ej. Festival de verano"></div><div class="field"><label>Fecha</label><input type="date" id="eventDate" value="${esc(draft.date||'')}"></div><div class="field"><label>Lugar</label><input id="eventPlace" value="${esc(draft.place||'')}" placeholder="Localidad"></div><div class="field full"><label>Participantes de la actuación</label><textarea id="eventParticipants" rows="5" placeholder="Un nombre por línea">${esc((draft.participants||[]).join("\n"))}</textarea><small>La Directora de baile, el Director y el Administrador total pueden modificar esta lista.</small></div><div class="field full dance-admin-box"><label>PDF para bailarines</label><div class="dance-upload-row"><input id="dancePdfFile" type="file" accept="application/pdf"><span id="dancePdfCurrent">${draft.dancePdfName?`Actual: ${esc(draft.dancePdfName)}`:'Sin PDF adjunto'}</span></div><small>El PDF se subirá a Supabase al guardar la actuación. Máximo recomendado: 15 MB.</small></div></div></div>`:'<div class="viewer-notice">Modo consulta: puedes preparar un repertorio temporal, pero solo el administrador puede guardar o modificar una actuación.</div>';
 app.innerHTML=`<div class="section-title"><h2>${heading}</h2><span>${selected.length} canciones</span></div>${adminForm}<div class="section-title"><h2>Orden</h2><button class="btn secondary small" id="addSongs">Añadir canciones</button></div>${selected.length?`<div class="stack">${selected.map((s,i)=>{const note=annotationFor(s.id);return `<div class="repertoire-item ${note?'has-note':''}"><div class="order">${i+1}</div><div data-openrep="${s.id}"><strong>${esc(s.title)}</strong><small style="display:block;color:var(--muted)">${esc(s.category)}${note?' · 📝 Anotación':''}</small></div><div class="actions">${state.isAdmin?`<button class="btn note-btn small ${note?'active':''}" data-note="${s.id}" title="Anotaciones">📝</button>`:''}<button class="btn secondary small" data-up="${i}">↑</button><button class="btn secondary small" data-down="${i}">↓</button><button class="btn ghost small" data-remove="${s.id}">✕</button></div></div>`}).join('')}</div><div class="toolbar" style="margin-top:16px"><button class="btn" id="perform">Modo actuación</button><button class="btn secondary" id="pdf">Crear PDF</button>${state.isAdmin?`<button class="btn secondary" id="savePerformance">${editing?'Guardar cambios':'Guardar actuación'}</button>`:''}${editing?'<button class="btn ghost" id="cancelPerformanceEdit">Cancelar edición</button>':'<button class="btn ghost" id="clearRep">Vaciar</button>'}</div>`:`<div class="empty">Todavía no has añadido canciones al repertorio.</div>${editing?'<div class="toolbar" style="margin-top:16px"><button class="btn ghost" id="cancelPerformanceEdit">Cancelar edición</button></div>':''}`}`;
 if(state.isAdmin){const updateDraft=()=>{state.performanceDraft={...(state.performanceDraft||{}),name:$('#eventName')?.value||'',date:$('#eventDate')?.value||'',place:$('#eventPlace')?.value||'',participants:String($('#eventParticipants')?.value||'').split(/\n+/).map(x=>x.trim()).filter(Boolean)};persist();schedulePerformanceAutosave()};['#eventName','#eventDate','#eventPlace','#eventParticipants'].forEach(q=>{const el=$(q);if(el)el.oninput=updateDraft});if($('#dancePdfFile'))$('#dancePdfFile').onchange=e=>{const f=e.target.files?.[0]||null;if(f&&f.type!=='application/pdf'){alert('Selecciona un archivo PDF.');e.target.value='';pendingDancePdfFile=null;return}pendingDancePdfFile=f;if(f)$('#dancePdfCurrent').textContent='Nuevo PDF: '+f.name}}
