function cloudStatusMarkup(){const net=navigator.onLine?'● En línea':'● Sin conexión';const netClass=navigator.onLine?'online':'offline';if(!CLOUD_ENABLED)return `<div class="sync-banner local"><strong>${net}</strong><span>Las actuaciones guardadas en este dispositivo siguen disponibles.</span></div>`;if(!navigator.onLine)return `<div class="sync-banner offline"><strong>${net}</strong><span>Puedes abrir las actuaciones marcadas como disponibles sin conexión. Al recuperar Internet, pulsa «Actualizar».</span><button class="btn ghost small" id="refreshCloud">Actualizar</button></div>`;if(state.cloudLoading)return '<div class="sync-banner loading"><strong>Sincronizando actuaciones…</strong><span>Conectando con la base de datos compartida.</span></div>';if(state.cloudError)return `<div class="sync-banner error"><strong>No se ha podido sincronizar</strong><span>${esc(state.cloudError)}</span><button class="btn secondary small" id="retryCloud">Reintentar</button></div>`;return `<div class="sync-banner online"><strong>${net} · ☁ Actuaciones compartidas</strong><span>${state.performances.length} actuación${state.performances.length===1?'':'es'} visible${state.performances.length===1?'':'s'} para todo el grupo.${state.cloudLastSync?' Última comprobación: '+new Date(state.cloudLastSync).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'}):''}</span><button class="btn ghost small" id="refreshCloud">Actualizar</button><button class="btn secondary small" id="testCloud">Comprobar conexión</button></div>`}
