function renderPerformances(){
 const legacy=localPerformanceBackup();state.performances=mergeOfflinePerformances(state.performances);
 app.innerHTML=`<div class="section-title"><h2>Actuaciones guardadas</h2><span>${state.performances.length}</span></div>${cloudStatusMarkup()}${state.isAdmin&&CLOUD_ENABLED&&legacy.length?`<div class="sync-migration"><div><strong>${legacy.length} actuaciones de versiones anteriores</strong><span>Puedes publicarlas para que aparezcan en todos los dispositivos.</span></div><button class="btn small" id="publishLegacy">Publicar ahora</button></div>`:''}${state.performances.length?`<div class="stack">${state.performances.map(p=>{const offline=isPerformanceOffline(p.id),participants=Array.isArray(p.participants)?p.participants:[];return `<article class="performance"><div class="performance-title-row"><h3>${esc(p.name)}</h3><div class="performance-badges">${CLOUD_ENABLED?'<span class="shared-badge">☁ Compartida</span>':''}${offline?'<span class="offline-badge">✓ Sin conexión</span>':''}</div></div><p>${esc(p.date)} ${p.place?'· '+esc(p.place):''}</p><p>${(p.songs||[]).length} canciones · ${participants.length} participantes${Object.values(p.annotations||{}).filter(Boolean).length?' · 📝 '+Object.values(p.annotations||{}).filter(Boolean).length+' con anotaciones':''}</p><div class="toolbar"><button class="btn small" data-load="${p.id}">Ver repertorio</button><button class="btn dancers-btn small" data-dancers="${p.id}">💃 Bailarines</button><button class="btn secondary small" data-participants="${p.id}">👥 Participantes</button>${state.isAdmin?`<button class="btn secondary small" data-guest-link="${p.id}">🔗 Invitado</button>`:''}${offline?`<button class="btn secondary small" data-remove-offline="${p.id}">Quitar sin conexión</button>`:`<button class="btn secondary small" data-save-offline="${p.id}">⬇ Guardar sin conexión</button>`}${state.isAdmin?`<button class="btn secondary small" data-edit-performance="${p.id}">Editar actuación</button><button class="btn ghost small" data-del="${p.id}">Eliminar</button>`:''}</div></article>`}).join('')}</div>`:`<div class="empty">${state.cloudLoading?'Sincronizando actuaciones…':'Todavía no hay actuaciones publicadas.'}</div>`}`;
 $$('[data-load]').forEach(b=>b.onclick=()=>openSavedPerformance(b.dataset.load));$$('[data-dancers]').forEach(b=>b.onclick=()=>openDancersSection(b.dataset.dancers));$$('[data-participants]').forEach(b=>b.onclick=()=>openParticipants(b.dataset.participants));$$('[data-guest-link]').forEach(b=>b.onclick=()=>createGuestAccess(b.dataset.guestLink));$$('[data-save-offline]').forEach(b=>b.onclick=()=>savePerformanceOffline(b.dataset.saveOffline));$$('[data-remove-offline]').forEach(b=>b.onclick=()=>removePerformanceOffline(b.dataset.removeOffline));$$('[data-edit-performance]').forEach(b=>b.onclick=()=>startPerformanceEdit(b.dataset.editPerformance));$$('[data-del]').forEach(b=>b.onclick=()=>deletePerformance(b.dataset.del));if($('#refreshCloud'))$('#refreshCloud').onclick=()=>refreshCloudPerformances();if($('#retryCloud'))$('#retryCloud').onclick=()=>refreshCloudPerformances();if($('#testCloud'))$('#testCloud').onclick=verifyCloudConnection;if($('#publishLegacy'))$('#publishLegacy').onclick=()=>publishLocalPerformances()
}
function renderSettings(){if(!isTotalAdmin())return nav('library');const legacy=localPerformanceBackup();app.innerHTML=`<div class="section-title"><h2>Datos y copias</h2></div><div class="data-grid"><section class="data-card"><h3>Exportar copia</h3><p>Descarga canciones, repertorio y actuaciones en un archivo JSON.</p><button class="btn" id="exportAll">Exportar copia</button></section><section class="data-card"><h3>Importar copia</h3><p>Restaura una copia guardada anteriormente.</p><button class="btn secondary" id="importAll">Seleccionar archivo</button></section>${CLOUD_ENABLED?`<section class="data-card"><h3>Actuaciones compartidas</h3><p>La base de datos contiene <strong>${state.performances.length}</strong> actuaciones visibles para todo el grupo.${legacy.length?` Hay ${legacy.length} actuaciones locales pendientes de publicar.`:''}</p>${legacy.length?'<button class="btn" id="publishLegacySettings">Publicar actuaciones locales</button>':'<span class="cloud-ok">✓ Sin datos locales pendientes</span>'}</section>`:''}<section class="data-card"><h3>Restaurar canciones iniciales</h3><p>Recupera las canciones suministradas. Se perderán tus ediciones.</p><button class="btn danger" id="resetSongs">Restaurar</button></section><section class="data-card"><h3>Resumen</h3><p><strong>${state.songs.length}</strong> canciones<br><strong>${state.performances.length}</strong> actuaciones guardadas<br><strong>${state.rep.length}</strong> canciones en repertorio actual</p></section></div>`;$('#exportAll').onclick=exportBackup;$('#importAll').onclick=()=>$('#importFile').click();if($('#publishLegacySettings'))$('#publishLegacySettings').onclick=publishLocalPerformances;$('#resetSongs').onclick=()=>{if(confirm('¿Restaurar las canciones iniciales? Se perderán tus cambios en las canciones.')){state.songs=clone(DEFAULT_SONGS);persist();toast('Canciones restauradas');renderSettings()}}}
function exportBackup(){const data={version:2,exportedAt:new Date().toISOString(),songs:state.songs,rep:state.rep,performances:state.performances,repAnnotations:state.repAnnotations};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='copia-cancionero-valdemedel-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href)}
$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.songs))throw Error();if(!confirm('¿Importar esta copia y sustituir los datos actuales?'))return;state.songs=data.songs;state.rep=Array.isArray(data.rep)?data.rep:[];state.performances=Array.isArray(data.performances)?data.performances:[];state.repAnnotations=data.repAnnotations&&typeof data.repAnnotations==='object'?data.repAnnotations:{};persist();toast('Copia importada');nav('library')}catch{alert('El archivo no es una copia válida.')}e.target.value=''};
function $(q){return document.querySelector(q)}function $$(q){return [...document.querySelectorAll(q)]}
async function forceAppRefresh(){
 const btn=$('#refreshAppBtn');
 if(btn){btn.disabled=true;btn.classList.add('is-refreshing');}
 try{
  if(CLOUD_ENABLED&&cloudClient) await refreshCloudPerformances({silent:true});
  if('serviceWorker' in navigator){
   const reg=await navigator.serviceWorker.getRegistration();
   if(reg){await reg.update();}
  }
  toast('Aplicación y actuaciones actualizadas');
  render();
 }catch(err){console.error(err);alert('No se ha podido actualizar: '+(err?.message||'error desconocido'))}
 finally{if(btn){btn.disabled=false;btn.classList.remove('is-refreshing')}}
}
function startAutomaticCloudRefresh(){
 const refresh=()=>{if(document.visibilityState==='visible'&&CLOUD_ENABLED&&cloudClient)refreshCloudPerformances({silent:true})};
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh()});
 window.addEventListener('focus',refresh);
 window.addEventListener('online',()=>{refresh();if(state.view==='performances')renderPerformances()});
 window.addEventListener('offline',()=>{state.cloudLoading=false;if(state.view==='performances')renderPerformances();toast('Modo sin conexión activado')});
 setInterval(refresh,5000);
}
$$('.bottom-nav button').forEach(b=>b.onclick=()=>nav(b.dataset.view));$('#homeBtn').onclick=()=>nav('management');if($('#refreshAppBtn'))$('#refreshAppBtn').onclick=forceAppRefresh;if($('#tunerBtn'))$('#tunerBtn').onclick=openTuner;$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem(STORAGE.theme,document.body.classList.contains('dark'))};$('#backupBtn').onclick=()=>{if(requireAdmin())exportBackup()};$('#adminBtn').onclick=adminLogin;if(localStorage.getItem(STORAGE.theme)==='true')document.body.classList.add('dark');renderChrome();render();initCloud();startAutomaticCloudRefresh();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});

/* ==========================================================
   v4.19 · Gestión del grupo: ensayos, encuestas, avisos,
   logística, vestuario y calendario compartido.
   ========================================================== */
const GROUP_STORAGE={profile:'vm_group_profile_v1',device:'vm_group_device_v1'};
const groupState={tab:'upcoming',events:[],responses:[],notices:[],loading:false,error:'',lastSync:null};
function groupDeviceId(){let id=localStorage.getItem(GROUP_STORAGE.device);if(!id){id='dev-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);localStorage.setItem(GROUP_STORAGE.device,id)}return id}
function groupProfile(){try{return JSON.parse(localStorage.getItem(GROUP_STORAGE.profile)||'null')||{name:'',section:''}}catch{return{name:'',section:''}}}
function saveGroupProfile(profile){localStorage.setItem(GROUP_STORAGE.profile,JSON.stringify(profile))}
function groupEsc(v){return esc(v==null?'':String(v))}
function eventKindLabel(kind){return kind==='rehearsal'?'Ensayo':'Encuesta de actuación'}
function eventKindClass(kind){return kind==='rehearsal'?'kind-rehearsal':'kind-poll'}
function responseFor(eventId){return groupState.responses.find(r=>String(r.event_id)===String(eventId)&&r.device_id===groupDeviceId())}
function dateHuman(date,time){if(!date)return 'Fecha pendiente';const d=new Date(date+'T12:00:00');const txt=d.toLocaleDateString('es-ES',{weekday:'short',day:'numeric',month:'short',year:'numeric'});return txt+(time?' · '+time.slice(0,5):'')}
async function loadGroupData(opts={}){if(!CLOUD_ENABLED||!cloudClient){groupState.error='La gestión compartida necesita conexión con Supabase.';return}if(!opts.silent)groupState.loading=true;try{const [ev,resp,noti]=await Promise.all([cloudClient.from('group_events').select('*').order('event_date',{ascending:true}),cloudClient.from('event_responses').select('*').order('updated_at',{ascending:false}),cloudClient.from('group_notices').select('*').order('created_at',{ascending:false})]);if(ev.error)throw ev.error;if(resp.error)throw resp.error;if(noti.error)throw noti.error;groupState.events=ev.data||[];groupState.responses=resp.data||[];groupState.notices=noti.data||[];groupState.error='';groupState.lastSync=new Date().toISOString()}catch(e){console.error('Gestión de grupo',e);groupState.error=e?.message||'No se han podido cargar los datos del grupo.'}finally{groupState.loading=false;if(state.view==='management')renderManagement()}}
function profileMarkup(){const p=groupProfile();return `<div class="profile-strip"><div><strong>${p.name?groupEsc(p.name):'Configura tu nombre'}</strong><span>${p.section?groupEsc(p.section):'Necesario para responder encuestas y asistencia'}</span></div><button class="btn ghost small" id="editGroupProfile">${p.name?'Editar':'Configurar'}</button></div>`}
function groupTabsMarkup(){const tabs=[['upcoming','Próximos'],['rehearsals','Ensayos'],['polls','Encuestas'],['notices','Avisos'],['calendar','Calendario']];return `<div class="group-tabs">${tabs.map(([id,label])=>`<button data-group-tab="${id}" class="${groupState.tab===id?'active':''}">${label}</button>`).join('')}</div>`}
function responseSummary(eventId){const rs=groupState.responses.filter(r=>String(r.event_id)===String(eventId));const count=a=>rs.filter(r=>r.answer===a).length;return `<div class="response-summary"><span class="answer-pill yes">Sí · ${count('yes')}</span><span class="answer-pill maybe">Pendiente · ${count('maybe')}</span><span class="answer-pill no">No · ${count('no')}</span></div>${state.isAdmin&&rs.length?`<div class="admin-stats">${rs.map(r=>`${groupEsc(r.member_name||'Sin nombre')} (${groupEsc(r.section||'sin sección')}): ${r.answer==='yes'?'Sí':r.answer==='no'?'No':'Pendiente'}${r.transport?' · '+groupEsc(r.transport):''}`).join('<br>')}</div>`:''}`}
function eventCard(e){const mine=responseFor(e.id);const logistics=e.logistics||{};return `<article class="group-card"><div class="group-card-head"><div><span class="kind-pill ${eventKindClass(e.kind)}">${eventKindLabel(e.kind)}</span><h3>${groupEsc(e.title)}</h3><div class="group-meta">${groupEsc(dateHuman(e.event_date,e.event_time))}${e.place?' · '+groupEsc(e.place):''}</div></div>${state.isAdmin?`<div><button class="btn ghost small" data-edit-event="${e.id}">Editar</button> <button class="btn ghost small" data-delete-event="${e.id}">Eliminar</button></div>`:''}</div>${e.details?`<p class="notice-body">${groupEsc(e.details)}</p>`:''}${(e.clothing||Object.values(logistics).some(Boolean))?`<div class="logistics-panel">${e.clothing?`<p><strong>Vestuario:</strong> ${groupEsc(e.clothing)}</p>`:''}${logistics.meeting?`<p><strong>Encuentro:</strong> ${groupEsc(logistics.meeting)}</p>`:''}${logistics.departure?`<p><strong>Salida:</strong> ${groupEsc(logistics.departure)}</p>`:''}${logistics.return_time?`<p><strong>Regreso:</strong> ${groupEsc(logistics.return_time)}</p>`:''}${logistics.transport?`<p><strong>Transporte:</strong> ${groupEsc(logistics.transport)}</p>`:''}${logistics.contact?`<p><strong>Contacto:</strong> ${groupEsc(logistics.contact)}</p>`:''}</div>`:''}<div class="response-box"><strong>${e.kind==='rehearsal'?'¿Asistirás al ensayo?':'¿Puedes asistir a esta actuación?'}</strong><div class="response-buttons"><button class="btn small ${mine?.answer==='yes'?'selected':''}" data-answer="yes" data-event-id="${e.id}">Sí</button><button class="btn small secondary ${mine?.answer==='maybe'?'selected':''}" data-answer="maybe" data-event-id="${e.id}">Pendiente</button><button class="btn small ghost ${mine?.answer==='no'?'selected':''}" data-answer="no" data-event-id="${e.id}">No</button></div>${mine?.notes?`<div class="group-meta">Tu nota: ${groupEsc(mine.notes)}</div>`:''}${responseSummary(e.id)}</div></article>`}
function noticesMarkup(){if(!groupState.notices.length)return '<div class="group-empty">No hay avisos publicados.</div>';return `<div class="group-grid">${groupState.notices.map(n=>`<article class="group-card ${n.important?'important':''}"><div class="group-card-head"><div><span class="kind-pill kind-notice">${n.important?'Aviso importante':'Aviso'}</span><h3>${groupEsc(n.title)}</h3><div class="group-meta">${new Date(n.created_at).toLocaleString('es-ES',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</div></div>${state.isAdmin?`<button class="btn ghost small" data-delete-notice="${n.id}">Eliminar</button>`:''}</div><p class="notice-body">${groupEsc(n.body)}</p></article>`).join('')}</div>`}
function calendarMarkup(){const all=[...groupState.events].sort((a,b)=>(a.event_date||'9999').localeCompare(b.event_date||'9999'));if(!all.length)return '<div class="group-empty">No hay fechas programadas.</div>';let month='';return all.map(e=>{const d=e.event_date?new Date(e.event_date+'T12:00:00'):null;const m=d?d.toLocaleDateString('es-ES',{month:'long',year:'numeric'}):'Sin fecha';const head=m!==month?(month=m,`<h3 class="calendar-month">${m.charAt(0).toUpperCase()+m.slice(1)}</h3>`):'';return head+`<div class="calendar-row"><div class="calendar-date">${d?d.getDate():'—'}<small>${d?d.toLocaleDateString('es-ES',{weekday:'short'}):''}</small></div><div><strong>${groupEsc(e.title)}</strong><div class="group-meta">${eventKindLabel(e.kind)}${e.event_time?' · '+e.event_time.slice(0,5):''}${e.place?' · '+groupEsc(e.place):''}</div></div><button class="btn ghost small" data-calendar-open="${e.id}">Ver</button></div>`}).join('')}
function renderManagement(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='management'));const today=new Date().toISOString().slice(0,10);let events=groupState.events;if(groupState.tab==='upcoming')events=events.filter(e=>!e.event_date||e.event_date>=today);if(groupState.tab==='rehearsals')events=events.filter(e=>e.kind==='rehearsal');if(groupState.tab==='polls')events=events.filter(e=>e.kind==='performance_poll');let body='';if(groupState.loading)body='<div class="group-empty">Actualizando la información del grupo…</div>';else if(groupState.error)body=`<div class="sync-banner error"><strong>No se ha podido actualizar</strong><span>${groupEsc(groupState.error)}</span><button class="btn small" id="retryGroup">Reintentar</button></div>`;else if(groupState.tab==='notices')body=noticesMarkup();else if(groupState.tab==='calendar')body=calendarMarkup();else body=events.length?`<div class="group-grid">${events.map(eventCard).join('')}</div>`:'<div class="group-empty">No hay elementos en esta sección.</div>';app.innerHTML=`<div class="section-title"><div><span class="eyebrow dark-eyebrow">Organización</span><h2>Gestión del grupo</h2></div><button class="btn ghost small" id="refreshGroup">↻ Actualizar</button></div><div class="group-shell">${profileMarkup()}${groupTabsMarkup()}${body}</div>${state.isAdmin?'<button class="group-fab" id="newGroupItem">＋ Nuevo</button>':''}`;bindManagementEvents()}
function bindManagementEvents(){$$('[data-group-tab]').forEach(b=>b.onclick=()=>{groupState.tab=b.dataset.groupTab;renderManagement()});if($('#refreshGroup'))$('#refreshGroup').onclick=()=>loadGroupData();if($('#retryGroup'))$('#retryGroup').onclick=()=>loadGroupData();if($('#editGroupProfile'))$('#editGroupProfile').onclick=openGroupProfile;$$('[data-answer]').forEach(b=>b.onclick=()=>answerGroupEvent(b.dataset.eventId,b.dataset.answer));$$('[data-edit-event]').forEach(b=>b.onclick=()=>openEventEditor(b.dataset.editEvent));$$('[data-delete-event]').forEach(b=>b.onclick=()=>deleteGroupEvent(b.dataset.deleteEvent));$$('[data-delete-notice]').forEach(b=>b.onclick=()=>deleteGroupNotice(b.dataset.deleteNotice));$$('[data-calendar-open]').forEach(b=>b.onclick=()=>{const e=groupState.events.find(x=>String(x.id)===String(b.dataset.calendarOpen));if(e)openEventEditor(e.id,true)});if($('#newGroupItem'))$('#newGroupItem').onclick=openNewGroupMenu}
function openGroupProfile(){const p=groupProfile();openModal(`<div class="modal-card management-modal"><div class="modal-head"><h2>Mi perfil en el grupo</h2><button class="icon-btn close-modal">×</button></div><div class="management-form"><label>Nombre y apellidos<input id="gpName" value="${groupEsc(p.name)}" placeholder="Tu nombre"></label><label>Sección<select id="gpSection"><option value="">Selecciona</option>${['Baile','Música','Canto','Infantil','Dirección','Otra'].map(x=>`<option ${p.section===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn" id="saveGp">Guardar perfil</button></div></div>`);$('.close-modal').onclick=closeModal;$('#saveGp').onclick=()=>{const profile={name:$('#gpName').value.trim(),section:$('#gpSection').value};if(!profile.name)return alert('Escribe tu nombre.');saveGroupProfile(profile);closeModal();renderManagement()}}
async function answerGroupEvent(eventId,answer){let p=groupProfile();if(!p.name){openGroupProfile();return toast('Configura tu nombre y vuelve a responder.')}const current=responseFor(eventId)||{};let notes=current.notes||'';if(answer==='no'||answer==='maybe'){const text=prompt('Observación opcional:',notes);if(text===null)return;notes=text.trim()}const row={id:eventId+'-'+groupDeviceId(),event_id:eventId,device_id:groupDeviceId(),member_name:p.name,section:p.section||'',answer,transport:current.transport||'',seats:Number(current.seats||0),notes,updated_at:new Date().toISOString()};try{const {data,error}=await cloudClient.from('event_responses').upsert(row,{onConflict:'id'}).select('*').single();if(error)throw error;groupState.responses=[data,...groupState.responses.filter(r=>r.id!==data.id)];toast('Respuesta guardada');renderManagement()}catch(e){alert('No se pudo guardar tu respuesta: '+(e?.message||'error desconocido'))}}
function openNewGroupMenu(){openModal(`<div class="modal-card management-modal"><div class="modal-head"><h2>Crear</h2><button class="icon-btn close-modal">×</button></div><div class="data-grid"><button class="data-card" data-new-kind="rehearsal"><h3>Ensayo</h3><p>Fecha, repertorio, asistencia y notas.</p></button><button class="data-card" data-new-kind="performance_poll"><h3>Encuesta de actuación</h3><p>Disponibilidad, logística y vestuario.</p></button><button class="data-card" data-new-kind="notice"><h3>Aviso</h3><p>Mensaje para todo el grupo.</p></button></div></div>`);$('.close-modal').onclick=closeModal;$$('[data-new-kind]').forEach(b=>b.onclick=()=>{const k=b.dataset.newKind;closeModal();k==='notice'?openNoticeEditor():openEventEditor(null,false,k)})}
function openEventEditor(id,readOnly=false,forcedKind=''){const e=groupState.events.find(x=>String(x.id)===String(id))||{id:'event-'+Date.now(),kind:forcedKind||'rehearsal',title:'',event_date:'',event_time:'',place:'',details:'',clothing:'',logistics:{},repertoire:[]};const l=e.logistics||{};openModal(`<div class="modal-card management-modal"><div class="modal-head"><h2>${readOnly?'Detalle':id?'Editar':'Nuevo'} ${eventKindLabel(e.kind).toLowerCase()}</h2><button class="icon-btn close-modal">×</button></div><div class="management-form"><label>Tipo<select id="geKind" ${readOnly?'disabled':''}><option value="rehearsal" ${e.kind==='rehearsal'?'selected':''}>Ensayo</option><option value="performance_poll" ${e.kind==='performance_poll'?'selected':''}>Encuesta de actuación</option></select></label><label>Título<input id="geTitle" value="${groupEsc(e.title)}" ${readOnly?'readonly':''} placeholder="Ej. Ensayo general / Festival de…"></label><div class="form-row"><label>Fecha<input id="geDate" type="date" value="${groupEsc(e.event_date||'')}" ${readOnly?'readonly':''}></label><label>Hora<input id="geTime" type="time" value="${groupEsc((e.event_time||'').slice(0,5))}" ${readOnly?'readonly':''}></label></div><label>Lugar<input id="gePlace" value="${groupEsc(e.place||'')}" ${readOnly?'readonly':''}></label><label>Detalles y objetivos<textarea id="geDetails" ${readOnly?'readonly':''}>${groupEsc(e.details||'')}</textarea></label><label>Vestuario<textarea id="geClothing" ${readOnly?'readonly':''} placeholder="Traje, calzado, complementos…">${groupEsc(e.clothing||'')}</textarea></label><h3>Logística</h3><div class="form-row"><label>Punto/hora de encuentro<input id="geMeeting" value="${groupEsc(l.meeting||'')}" ${readOnly?'readonly':''}></label><label>Hora de salida<input id="geDeparture" value="${groupEsc(l.departure||'')}" ${readOnly?'readonly':''}></label></div><div class="form-row"><label>Regreso previsto<input id="geReturn" value="${groupEsc(l.return_time||'')}" ${readOnly?'readonly':''}></label><label>Transporte<input id="geTransport" value="${groupEsc(l.transport||'')}" ${readOnly?'readonly':''}></label></div><label>Contacto de organización<input id="geContact" value="${groupEsc(l.contact||'')}" ${readOnly?'readonly':''}></label>${readOnly?'':`<button class="btn" id="saveGe">Guardar y publicar</button>`}</div></div>`);$('.close-modal').onclick=closeModal;if(!readOnly)$('#saveGe').onclick=()=>saveGroupEvent(e.id)}
async function saveGroupEvent(id){if(!requireAdmin())return;const row={id,kind:$('#geKind').value,title:$('#geTitle').value.trim(),event_date:$('#geDate').value||null,event_time:$('#geTime').value||null,place:$('#gePlace').value.trim(),details:$('#geDetails').value.trim(),clothing:$('#geClothing').value.trim(),repertoire:[],logistics:{meeting:$('#geMeeting').value.trim(),departure:$('#geDeparture').value.trim(),return_time:$('#geReturn').value.trim(),transport:$('#geTransport').value.trim(),contact:$('#geContact').value.trim()},updated_at:new Date().toISOString()};if(!row.title)return alert('Escribe un título.');try{const {data,error}=await cloudClient.from('group_events').upsert(row,{onConflict:'id'}).select('*').single();if(error)throw error;groupState.events=[...groupState.events.filter(x=>x.id!==data.id),data].sort((a,b)=>(a.event_date||'9999').localeCompare(b.event_date||'9999'));closeModal();toast('Publicado para todo el grupo');renderManagement()}catch(e){alert('No se pudo publicar: '+(e?.message||'error desconocido'))}}
