 const clean=String(email||'').trim().toLowerCase();
 if(!clean)throw new Error('Escribe tu correo.');
 if(!password)throw new Error('Escribe tu contraseña.');
 const {data,error}=await cloudClient.auth.signInWithPassword({email:clean,password});
