/* ==========================================================
   v4.29 · Canciones compartidas y corrección Villar de Rena
   ========================================================== */
const SHARED_SONGS_SYNC_KEY='vm_shared_songs_v429';
const VILLAR_RABIOSA_FIX_KEY='vm_fix_villar_rena_rabiosa_v429';
function normalizaV429(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function sharedSongToRow(song){return {id:String(song.id),title:song.title||'',data:clone(song),updated_at:song.updatedAt||new Date().toISOString()}}
function sharedSongFromRow(row){const song=row&&row.data&&typeof row.data==='object'?clone(row.data):{};song.id=String(row.id||song.id||uid());song.title=row.title||song.title||'Canción';song.updatedAt=row.updated_at||song.updatedAt||new Date().toISOString();return song}
async function upsertSharedSong(song){if(!cloudClient)throw new Error('Supabase no está conectado.');const {data,error}=await cloudClient.from('shared_songs').upsert(sharedSongToRow(song),{onConflict:'id'}).select('*').single();if(error)throw error;return sharedSongFromRow(data)}
async function loadSharedSongs(){if(!cloudClient||!navigator.onLine)return;const {data,error}=await cloudClient.from('shared_songs').select('*').order('title',{ascending:true});if(error)throw error;let changed=false;for(const row of (data||[])){const incoming=sharedSongFromRow(row),i=state.songs.findIndex(x=>String(x.id)===String(incoming.id));if(i<0){state.songs.push(incoming);changed=true}else if(String(incoming.updatedAt||'')>String(state.songs[i].updatedAt||'')){state.songs[i]=incoming;changed=true}}if(changed){state.songs.sort((a,b)=>a.title.localeCompare(b.title,'es'));localStorage.setItem(STORAGE.songs,JSON.stringify(state.songs));render()}}
async function publishLocalCustomSongs(){if(!cloudClient||!canManageContent())return;const defaults=new Set(DEFAULT_SONGS.map(x=>String(x.id)));const custom=state.songs.filter(x=>!defaults.has(String(x.id)));for(const song of custom){try{await upsertSharedSong(song)}catch(e){console.warn('No se pudo publicar canción local',song.title,e)}}localStorage.setItem(SHARED_SONGS_SYNC_KEY,'1')}
async function ensureRondenaRabiosaVillar(){if(localStorage.getItem(VILLAR_RABIOSA_FIX_KEY)==='1'||!cloudClient||!canManageContent())return;const song=state.songs.find(x=>normalizaV429(x.title)==='rondena rabiosa');if(!song)return;const perf=state.performances.find(x=>normalizaV429((x.name||'')+' '+(x.place||'')).includes('villar de rena'));if(!perf)return;const songs=[...(perf.songs||[])].filter(id=>String(id)!==String(song.id));songs.splice(Math.min(16,songs.length),0,song.id);const updated={...perf,songs,updatedAt:new Date().toISOString()};try{await upsertSharedSong(song);const confirmed=await upsertCloudPerformance(updated);const i=state.performances.findIndex(x=>String(x.id)===String(perf.id));if(i>=0)state.performances[i]=confirmed;persist();localStorage.setItem(VILLAR_RABIOSA_FIX_KEY,'1');toast('Rondeña Rabiosa añadida como nº 17 en Villar de Rena');if(state.view==='performances'||state.view==='repertoire')render()}catch(e){console.error('No se pudo corregir Villar de Rena',e)}}
const initCloudV429=initCloud;initCloud=async function(){await initCloudV429();try{await loadSharedSongs();if(canManageContent()&&!localStorage.getItem(SHARED_SONGS_SYNC_KEY))await publishLocalCustomSongs();await ensureRondenaRabiosaVillar()}catch(e){console.warn('Sincronización de canciones v4.29',e)}};
const refreshCloudPerformancesV429=refreshCloudPerformances;refreshCloudPerformances=async function(opts={}){const out=await refreshCloudPerformancesV429(opts);try{await loadSharedSongs();await ensureRondenaRabiosaVillar()}catch(e){console.warn(e)}return out};
